import { Group, Mesh, PlaneGeometry, BoxGeometry } from 'three/webgpu';
import { MeshStandardNodeMaterial } from 'three/webgpu';
import gsap from 'gsap';

export default function createNode(config, ctx) {
  const group = new Group();
  const materials = [];
  const textures = [];
  const tweens = [];
  let animationFrame = null;

  // Text content
  const headline = 'Inside the atelier';
  const captions = [
    'DIAL ROOM',
    'ESCAPEMENT BENCH',
    'CNC HALL',
    'FINISHING LAB',
    'ARCHIVE VAULT',
    'ASSEMBLY LINE ONE'
  ];

  // Headline (pinned, not scrolling)
  const headlineText = ctx.fontAtlas.createText(headline, {
    fontSize: 68,
    color: '#e8ecf2',
    align: 'left'
  });
  headlineText.position.set(-1.6, 1.9, 0);
  group.add(headlineText);

  // Scrolling content container
  const scrollGroup = new Group();
  scrollGroup.position.x = 0.9;
  group.add(scrollGroup);

  // Plate data
  const plates = [];

  // Load base texture
  ctx.textureLoader.loadTexture('/prism-mock/home/nodes/feature-card.png').then((tex) => {
    tex.colorSpace = 'srgb';
    textures.push(tex);
    // Apply to all plates
    plates.forEach(p => {
      p.material.map = tex;
      p.material.needsUpdate = true;
    });
  });

  // Create 6 image plates
  for (let i = 0; i < 6; i++) {
    const yPos = i * 1.5;

    // Main plate (1.9 x 1.2 units, 16:10 aspect)
    const planeGeom = new PlaneGeometry(1.9, 1.2);
    const plateMat = new MeshStandardNodeMaterial({
      color: 0xffffff,
      roughness: 0.6,
      metalness: 0.1,
      clearcoat: 0.1
    });
    materials.push(plateMat);

    const plateMesh = new Mesh(planeGeom, plateMat);
    plateMesh.position.y = yPos;
    scrollGroup.add(plateMesh);

    // Bevel frame (0.03 units, machined ink #16161d with brushed highlight)
    const bevelMat = new MeshStandardNodeMaterial({
      color: 0x16161d,
      roughness: 0.5,
      metalness: 0.5,
      emissive: 0x1a1a22,
      emissiveIntensity: 0.15
    });
    materials.push(bevelMat);

    // Bevel segments: top, bottom, left, right
    const bevels = [
      { size: [1.96, 0.03, 1], offset: [0, 0.6, 0.005] },
      { size: [1.96, 0.03, 1], offset: [0, -0.6, 0.005] },
      { size: [0.03, 1.2, 1], offset: [-0.95, 0, 0.005] },
      { size: [0.03, 1.2, 1], offset: [0.95, 0, 0.005] }
    ];

    bevels.forEach(bevel => {
      const bevelGeom = new BoxGeometry(...bevel.size);
      const bevelMesh = new Mesh(bevelGeom, bevelMat);
      bevelMesh.position.set(
        bevel.offset[0],
        bevel.offset[1] + yPos,
        bevel.offset[2]
      );
      scrollGroup.add(bevelMesh);
    });

    // Accent strip (left edge, #ff2a38 at emissive 1.4)
    const stripGeom = new PlaneGeometry(0.03, 1.2);
    const stripMat = new MeshStandardNodeMaterial({
      color: 0x000000,
      emissive: 0xff2a38,
      emissiveIntensity: 1.4,
      roughness: 0.2,
      metalness: 0.7
    });
    materials.push(stripMat);

    const stripMesh = new Mesh(stripGeom, stripMat);
    stripMesh.position.set(-0.95, yPos, 0.01);
    scrollGroup.add(stripMesh);

    // Caption text (fades up at x=-1.6 when focused)
    const caption = ctx.fontAtlas.createText(captions[i], {
      fontSize: 18,
      color: '#e8ecf2',
      align: 'left'
    });
    caption.position.set(-1.6, yPos - 0.7, 0.01);
    caption.traverse(child => {
      if (child.material) {
        child.material.transparent = true;
        child.material.opacity = 0.4;
      }
    });
    scrollGroup.add(caption);

    plates.push({
      index: i,
      plateMesh,
      material: plateMat,
      caption,
      baseY: yPos
    });
  }

  // Scroll state and inertial motion
  let scrollPos = 0;
  let targetScrollPos = 0;
  let scrollVel = 0;
  const scrollDamping = 0.12;
  const loopHeight = 9.0; // 6 plates × 1.5 units
  let focusedIndex = 0;

  const updateFrame = () => {
    // Inertial motion with damping
    const delta = targetScrollPos - scrollPos;
    if (Math.abs(delta) > 0.0001) {
      scrollVel = delta * (1 - scrollDamping);
      scrollPos += scrollVel;
    }

    // Seamless loop: modulo 9.0 units
    const displayPos = ((scrollPos % loopHeight) + loopHeight) % loopHeight;
    scrollGroup.position.y = -displayPos;

    // Find plate nearest to y=0 (focused plate)
    let closestDist = Infinity;
    let closestIdx = 0;

    plates.forEach((plate, idx) => {
      const worldY = scrollGroup.position.y + plate.baseY;
      const distToCenter = Math.abs(worldY);
      if (distToCenter < closestDist) {
        closestDist = distToCenter;
        closestIdx = idx;
      }
    });

    // Update focus state
    if (closestIdx !== focusedIndex) {
      const prevPlate = plates[focusedIndex];
      const nextPlate = plates[closestIdx];

      // Scale animations (1.0 → 1.06 with easing)
      const t1 = gsap.to(prevPlate.plateMesh.scale, {
        x: 1.0,
        y: 1.0,
        duration: 0.35,
        ease: 'cubic-bezier(0.215, 0.61, 0.355, 1)'
      });
      tweens.push(t1);

      const t2 = gsap.to(nextPlate.plateMesh.scale, {
        x: 1.06,
        y: 1.06,
        duration: 0.35,
        ease: 'cubic-bezier(0.215, 0.61, 0.355, 1)'
      });
      tweens.push(t2);

      // Caption fade animations
      prevPlate.caption.traverse(child => {
        if (child.material) {
          const t3 = gsap.to(child.material, {
            opacity: 0.4,
            duration: 0.3
          });
          tweens.push(t3);
        }
      });

      nextPlate.caption.traverse(child => {
        if (child.material) {
          const t4 = gsap.to(child.material, {
            opacity: 1.0,
            duration: 0.3
          });
          tweens.push(t4);
        }
      });

      focusedIndex = closestIdx;
    }

    animationFrame = requestAnimationFrame(updateFrame);
  };

  updateFrame();

  // Scroll event handler
  group.userData.handlers = {
    scroll: (event) => {
      const scrollDelta = event.deltaY ?? event.delta ?? event.amount ?? 0;
      // 1.5 units per viewport scroll, scaled for reasonableness
      targetScrollPos += scrollDelta * 0.0015;
    }
  };

  // Apply fly-through primitive (camera dollies 2.5 units deeper on scroll)
  if (ctx.primitives && typeof ctx.primitives['fly-through'] === 'function') {
    const flyResult = ctx.primitives['fly-through'](group, {
      depthUnits: 2.5
    });
    if (flyResult && typeof flyResult.cleanup === 'function') {
      group.userData._flyCleanup = flyResult.cleanup;
    }
  }

  // Cleanup
  group.userData.cleanup = () => {
    if (animationFrame !== null) {
      cancelAnimationFrame(animationFrame);
    }
    tweens.forEach(tween => {
      if (tween && typeof tween.kill === 'function') {
        tween.kill();
      }
    });
    if (group.userData._flyCleanup) {
      group.userData._flyCleanup();
    }
    materials.forEach(mat => mat.dispose());
    textures.forEach(tex => tex.dispose());
  };

  return group;
}
